INSERT INTO `books` VALUES (4,'Nhà Giả Kim','Cuốn tiểu thuyết nổi tiếng của Paulo Coelho kể về hành trình đi tìm kho báu và ý nghĩa cuộc đời của chàng chăn cừu Santiago.',89000.00,49,10,'http://localhost:8080/uploads/nha_gia_kim.jpg','2026-03-19 20:07:52',_binary '\0'),(6,'Đắc Nhân Tâm','Cuốn sách kinh điển về nghệ thuật giao tiếp và chinh phục lòng người của Dale Carnegie.',98000.00,80,10,'http://localhost:8080/uploads/dac_nhan_tam.jpg','2026-03-19 20:11:13',_binary '\0'),(20,'Dế Mèn Phiêu Lưu Ký','Câu chuyện phiêu lưu của chú dế mèn dũng cảm qua ngòi bút tài hoa của Tô Hoài.',55000.00,88,0,'http://localhost:8080/uploads/de_men_phieu_luu_ki.jpg','2026-03-23 09:57:01',_binary '\0'),(22,'Tắt Đèn','Tác phẩm hiện thực xuất sắc của Ngô Tất Tố về số phận người nông dân Việt Nam trước Cách mạng.',48000.00,80,0,'http://localhost:8080/uploads/tat_den.jpg','2026-03-23 09:57:01',_binary ''),(25,'Trại Súc Vật','Ngụ ngôn chính trị sắc bén của George Orwell về cách quyền lực bị lạm dụng.',85000.00,50,5,'http://localhost:8080/uploads/trai_suc_vat.jpg','2026-03-23 09:57:01',_binary ''),(28,'Truyện Kiều','Kiệt tác văn học Việt Nam của Nguyễn Du, kể về cuộc đời đầy bi kịch của nàng Kiều tài sắc.',75000.00,0,0,'http://localhost:8080/uploads/truyen_kieu.jpg','2026-03-23 09:57:01',_binary '\0'),(29,'Lão Hạc','Truyện ngắn cảm động của Nam Cao về người nông dân nghèo giàu lòng tự trọng và tình yêu thương.',42000.00,84,0,'http://localhost:8080/uploads/lao_hac.jpg','2026-03-23 09:57:01',_binary '\0'),(30,'Bên Nhau Trọn Đời','Câu chuyện tình yêu đầy cảm động giữa Hà Dĩ Thâm và Triệu Mặc Sênh — từ ghế nhà trường qua bao biến cố mới về bên nhau. Tác phẩm đã được chuyển thể thành phim truyền hình đình đám.',89000.00,98,10,'http://localhost:8080/uploads/ben_nhau_tron_doi.jpg','2026-03-23 10:24:04',_binary '\0'),(31,'Yêu Em Từ Cái Nhìn Đầu Tiên','Chuyện tình ngọt ngào giữa Tiêu Nại và Bối Vi Vi bắt đầu từ thế giới game online. Mối tình xứng đôi vừa lứa, trong sáng và đầy lãng mạn của tuổi học trò.',85000.00,89,5,'http://localhost:8080/uploads/yeu_em_tu_cai_nhin_dau_tien.jpg','2026-03-23 10:24:04',_binary '\0'),(32,'Mãi Mãi Là Bao Xa','Câu chuyện tình yêu xa của nhà khoa học và cô nữ sinh năng động. Sau bao năm xa cách tưởng chừng không thể gặp lại, họ đã quay về bên nhau sống cuộc đời hạnh phúc.',82000.00,84,0,'http://localhost:8080/uploads/mai_mai_la_bao_xa.jpg','2026-03-23 10:24:04',_binary '\0'),(34,'Thất Tịch Không Mưa','Mối tình buồn đầy xúc động của Thẩm Thiên Tình — yêu thầm người anh trai cùng cha khác mẹ suốt bao năm. Câu chuyện ngược tâm khiến hàng triệu độc giả rơi nước mắt.',88000.00,78,10,'http://localhost:8080/uploads/that_tich_khong_mua.jpg','2026-03-23 10:24:04',_binary '\0'),(37,'Tam Sinh Tam Thế Chẩm Thượng Thư','Chuyện tình xuyên ba kiếp luân hồi của Bạch Phượng Cửu và Dạ Hoa — Đế quân Thiên Cung. Bối cảnh tiên giới huyền ảo tráng lệ với những tình tiết bi thương, lãng mạn khó quên.',95000.00,84,10,'http://localhost:8080/uploads/tam_sinh_tam_the.jpg','2026-03-23 10:24:04',_binary '\0'),(40,'Khó dỗ dành','Thông tin chi tiết về sách truyện Khó Dỗ Dành:\nTác giả: Trúc Dĩ.\nThể loại: Ngôn tình, hiện đại, lãng mạn, gương vỡ lại lành.\nNhân vật chính: Ôn Dĩ Phàm (xinh đẹp, nội tâm phức tạp) và Tang Diên (thâm tình, kiêu ngạo).\nNội dung: Câu chuyện kể về sự gặp lại của hai người bạn học cũ. Dù trải qua nhiều hiểu lầm và thử thách, họ vẫn dành cho nhau tình yêu chân thành và nỗ lực vượt qua khó khăn để đến với nhau.',2000.00,0,0,'http://localhost:8080/uploads/kho_do_danh_2.jpg','2026-03-25 22:41:16',_binary '\0'),(41,'Hồ Điệp và Kình Ngư','“Tuổi thọ của một con bướm nằm trong khoảng ba ngày đến một tháng, mà đa số các con bướm chỉ có một tuần tuổi thọ.”\n\n“Em cũng giống chúng vậy, sinh mạng chỉ kéo dài vài tháng thôi, có lẽ còn ngắn hơn thế nữa.”\n\n_\n\nLần đầu tiên Hồ Điệp gặp Kinh Du, anh cho rằng cô là thiếu nữ chán đời muốn tự tử.\n\nLần thứ hai gặp nhau, anh chẳng mấy bận tâm nói với Hồ Điệp rằng: “Hôm nay nếu cậu nhảy xuống thì tôi sẽ không cứu cậu nữa đâu.”\n\nVề sau lại đến cô bảo anh: “Kinh Du, đừng đau khổ vì em.”\n\nThật lâu sau này, Kinh Du trở lại sân đấu và đạt được vinh quang thuộc về mình.\n\nDưới ánh đèn sáng ngời, anh chợt nhớ lại giọng nói và dáng vẻ của cô thiếu nữ ấy rồi thốt ra một câu không đầu không đuôi trước muôn vàn người — “Anh không đau khổ, chỉ là cảm thấy vào khoảnh khắc này, có em ở đây thì sẽ tốt hơn biết bao.”\n\n“Anh là cá voi ngao du đại dương, chợt vào một ngày tình cờ, một chú bướm vô tình xông vào tần số của anh. Đó là giây phút đẹp đẽ nhất trong cuộc đời anh.”\n\n*\n\nThiếu nữ mắc bệnh ung thư x Thiếu niên bơi lội\n\nTruyện ngắn/BE\n\nHồ Điệp là vận động viên trượt băng nghệ thuật, sau đó cô qua đời vào mùa hè\n\nCâu đầu tiên trong văn án là nguồn internet\n\nTag: Hoa quý mùa mưa, nhân duyên tình cờ gặp gỡ, thiên chi kiều tử\n\nNhân vật chính: Hồ Điệp, Kinh Du\n\nMột câu giới thiệu đơn giản: Khoảnh khắc đẹp đẽ nhất trong cuộc đời\n\nLập ý: Dù cho con đường phía trước đầy khó khăn, cũng đừng quên mất ước mơ',2000.00,0,0,'http://localhost:8080/uploads/HoDiep_KinhNgu.jpg','2026-03-29 21:49:46',_binary '\0'),(42,'Tướng môn độc hậu','Đích nữ nhà tướng quân, tính tình ôn nhu trầm tĩnh, lưu luyến si mê Định Vương, hy sinh vì tình.\n\nSáu năm theo phò tá chỉ mong trở thành mẫu nghi thiên hạ.\n\nGiúp hắn đấu tranh giành thiên hạ, lập quốc hưng thịnh, còn mạo hiểm ở lại nơi đất khách quê người làm con tin, nhưng sau năm năm trở về, hậu cung đã không còn chỗ dung thân.\n\nMỹ nhân trong ngực hắn kiều diễm tươi cười: “Tỷ tỷ, giang sơn nay đã yên ổn rồi, ngươi cũng nên lui đi.”\n\nNữ nhi chết thảm, Thái tử bị phế. Thẩm gia cả đội trung liệt, không một ai may mắn thoát khỏi. Toàn bộ sụp đổ, tang thương bao trùm.\n\nThẩm Diệu không thể nào nghĩ tới, tình cảm phu thê hoạn nạn có nhau, tình chàng ý thiếp ngày nào lại thành một hồi gặp dịp thì chơi, thật đáng chê cười!\nHắn nói: “Nể tình ngươi theo trẫm hai mươi năm, ban cho ngươi toàn thây, mau tạ ơn”\n\nBa thước lụa trắng ban xuống, Thẩm Diệu lập lời thề độc: “Ngày ta chết, mọi thứ sẽ cùng chôn theo!”\n\nTrọng sinh vào năm mười bốn tuổi, lúc bi kịch chưa xảy ra, người thân vẫn còn, nàng vẫn là đích nữ nhà tướng quân ôn nhu nho nhã.\nThân thích luôn rắp tâm hại người, đường tỷ đường muội lại ác độc vô tình, di nương mới vào cửa như hổ rình mồi, còn có tra nam ý muốn giở trò đều có đủ?\n\nCó gia tộc muốn bảo hộ, đại thù muốn báo, còn có giang sơn đế vị, cũng muốn chia một phần. Đời này, thử xem là ai đấu với ai!\n\nNhưng Tiêu hầu gia Tạ gia, mang thương cưỡi ngựa vô cùng kiệt xuất, đứng ở trên đầu tường nhà nàng ngạo nghễ: “Chỉ là cái hoàng quyền thôi, nhớ kỹ, thiên hạ thuộc về nàng, nhưng nàng— là của ta!”',240000.00,5,12,'http://localhost:8080/uploads/tuong_mon_doc_hau.jpg','2026-04-02 09:09:49',_binary '\0'),(43,'Harry Potter và hòn đá phù thủy','Nhân vật chính của bộ truyện là cậu bé thiếu niên Harry Potter. Bố mẹ của cậu bị Chúa tể Voldemort sát hại bởi vì một lời tiên tri. Khi hắn định giết Harry thì bị tiêu diệt bởi Lời nguyền chết chóc, biến thành một linh hồn không sống cũng không chết. Ngay lúc đó, trên trán Harry xuất hiện dấu hiệu duy nhất của lời nguyền, một tia chớp đặc biệt.\n\nKhi biết cậu là người duy nhất sống sót trước lời nguyền, cộng đồng phù thủy đã gọi cậu là \"Đứa bé sống sót\". Sau cái chết của bố mẹ, cậu sống cùng với dì dượng. Nhưng vì gia đình dì cậu ghét những người có quyền năng phép thuật, nên không hề tiết lộ cho Harry biết về khả năng của mình. Thế rồi, đến ngày sinh nhật thứ 11, thân phận của cậu cũng bị hé lộ.\n\nNhững ngày tháng sau đó, cậu đi học tại trường Hogwarts – một trường học phép thuật và đã được học thêm nhiều phép thuật kì diệu. Tại đó, cậu có cho mình một nhóm bạn thân, gồm Ron và Hermion. Bộ ba đã gắn bó, đồng hành với nhau bất chấp sự khác biệt về thân phận, dòng máu. Câu chuyện của Harry ở trường học phép thuật cũng dần dần được hé mở…',150000.00,4,10,'http://localhost:8080/uploads/hon_da_phu_thuy.jpg','2026-04-05 13:50:29',_binary '\0'),(44,'Harry Potter và Phòng chứa bí mật','Nhân vật chính của bộ truyện là cậu bé thiếu niên Harry Potter. Bố mẹ của cậu bị Chúa tể Voldemort sát hại bởi vì một lời tiên tri. Khi hắn định giết Harry thì bị tiêu diệt bởi Lời nguyền chết chóc, biến thành một linh hồn không sống cũng không chết. Ngay lúc đó, trên trán Harry xuất hiện dấu hiệu duy nhất của lời nguyền, một tia chớp đặc biệt.\n\nKhi biết cậu là người duy nhất sống sót trước lời nguyền, cộng đồng phù thủy đã gọi cậu là \"Đứa bé sống sót\". Sau cái chết của bố mẹ, cậu sống cùng với dì dượng. Nhưng vì gia đình dì cậu ghét những người có quyền năng phép thuật, nên không hề tiết lộ cho Harry biết về khả năng của mình. Thế rồi, đến ngày sinh nhật thứ 11, thân phận của cậu cũng bị hé lộ.\n\nNhững ngày tháng sau đó, cậu đi học tại trường Hogwarts – một trường học phép thuật và đã được học thêm nhiều phép thuật kì diệu. Tại đó, cậu có cho mình một nhóm bạn thân, gồm Ron và Hermion. Bộ ba đã gắn bó, đồng hành với nhau bất chấp sự khác biệt về thân phận, dòng máu. Câu chuyện của Harry ở trường học phép thuật cũng dần dần được hé mở…',160000.00,5,15,'http://localhost:8080/uploads/phong_chua_bi_mat.jpg','2026-04-05 14:04:00',_binary '\0'),(45,'Trọn bộ 2 quyển - Khó Dỗ Dành','Sau sáu năm, Ôn Dĩ Phàm vô tình gặp lại Tang Diên tại một quán bar. Hai người là bạn học cùng lớp cấp 3 và khi đó cô đã từng phải lòng anh, tuy nhiên vì một số lý do, cô đã buộc phải từ chối tình cảm của anh khiến họ rời xa nhau. Để không cảm thấy ngượng ngùng, hai người đã giả vờ không quen biết nhau.[6] Vì nhiều tình huống mà hai người buộc phải đối mặt với nhau khi cùng sống chung dưới một mái nhà. Bản chất mối quan hệ của họ thay đổi khi Ôn Dĩ Phàm biết được rằng cô bị mộng du vào ban đêm. Tình trạng này của cô đã trở nên tồi tệ hơn do một số tổn thương đến từ gia đình trong quá khứ, và khi cô phát hiện ra mình tỉnh dậy trong phòng của Tang Diên thì từ đó cuộc sống của hai người ngày càng trở nên gắn kết với nhau hơn.',284700.00,6,0,'http://localhost:8080/uploads/kho_do_danh.jpg','2026-04-17 11:19:31',_binary '\0');
