INSERT INTO `chatbot_logs` VALUES (1,10,'Gß╗úi ├╜ s├ích hay cho t├┤i','Bß║ín ─æang t├¼m s├ích hay ─æß╗â ─æß╗ìc? T├┤i c├│ mß╗Öt sß╗æ gß╗úi ├╜ nh╞░ sau:\n\n- Nß║┐u bß║ín th├¡ch tiß╗âu thuyß║┐t kinh ─æiß╗ân, c├│ thß╗â xem x├⌐t \"Truyß╗çn Kiß╗üu\" cß╗ºa Nguyß╗àn Du (75,000─æ, hß║┐t h├áng) hoß║╖c \"1984\" cß╗ºa George Orwell (115,000─æ, c├▓n 45 quyß╗ân).\n- Nß║┐u bß║ín th├¡ch tiß╗âu thuyß║┐t hiß╗çn ─æß║íi, c├│ thß╗â xem x├⌐t \"B├¬n Nhau Trß╗ìn ─Éß╗¥i\" cß╗ºa Cß╗æ Mß║ín (89,000─æ, c├▓n 99 quyß╗ân) hoß║╖c \"M├úi M├úi L├á Bao Xa\" cß╗ºa Diß╗çp Lß║íc V├┤ T├óm (82,000─æ, c├▓n 85 quyß╗ân).\n- Nß║┐u bß║ín th├¡ch tiß╗âu thuyß║┐t t├óm l├╜, c├│ thß╗â xem x├⌐t \"It - G├ú Hß╗ü Ma Qu├íi\" cß╗ºa Stephen King (175,000─æ, c├▓n 25 quyß╗ân) hoß║╖c \"The Shining - Kh├ích Sß║ín Ma\" cß╗ºa Stephen King (155,000─æ, c├▓n 30 quyß╗ân).\n\nHy vß╗ìng nhß╗»ng gß╗úi ├╜ n├áy sß║╜ gi├║p bß║ín t├¼m ─æ╞░ß╗úc s├ích ph├╣ hß╗úp!','2026-03-30 05:28:53'),(2,10,'mß╗Öt sß╗æ s├ích ng├┤n t├¼nh hay','Bookish c├│ mß╗Öt sß╗æ s├ích ng├┤n t├¼nh hay m├á bß║ín c├│ thß╗â tham khß║úo:\n\n1. B├¬n Nhau Trß╗ìn ─Éß╗¥i (Cß╗æ Mß║ín, 89,000─æ, c├▓n 99 quyß╗ân): ─É├óy l├á mß╗Öt trong nhß╗»ng bß╗Ö ng├┤n t├¼nh hay nhß║Ñt cß╗ºa t├íc giß║ú Cß╗æ Mß║ín, kß╗â vß╗ü mß╗æi quan hß╗ç giß╗»a hai ng╞░ß╗¥i tß╗½ nhß╗Å ─æß║┐n lß╗¢n.\n2. Y├¬u Em Tß╗½ C├íi Nh├¼n ─Éß║ºu Ti├¬n (Cß╗æ Mß║ín, 85,000─æ, c├▓n 90 quyß╗ân): Bß╗Ö ng├┤n t├¼nh kh├íc cß╗ºa Cß╗æ Mß║ín, kß╗â vß╗ü t├¼nh y├¬u ─æß║ºu ti├¬n cß╗ºa hai ng╞░ß╗¥i v├á sß╗▒ ph├ít triß╗ân cß╗ºa mß╗æi quan hß╗ç.\n3. M├úi M├úi L├á Bao Xa (Diß╗çp Lß║íc V├┤ T├óm, 82,000─æ, c├▓n 85 quyß╗ân): Bß╗Ö ng├┤n t├¼nh cß╗ºa Diß╗çp Lß║íc V├┤ T├óm, kß╗â vß╗ü mß╗æi quan hß╗ç phß╗⌐c tß║íp giß╗»a hai ng╞░ß╗¥i v├á sß╗▒ kh├ím ph├í vß╗ü t├¼nh y├¬u.\n\nHy vß╗ìng nhß╗»ng gß╗úi ├╜ n├áy sß║╜ gi├║p bß║ín t├¼m ─æ╞░ß╗úc cuß╗æn s├ích ng├┤n t├¼nh ph├╣ hß╗úp!','2026-03-30 05:30:07'),(3,NULL,'Gß╗úi ├╜ s├ích hay cho t├┤i','Dß║┐ M├¿n Phi├¬u L╞░u K├╜ cß╗ºa T├┤ Ho├ái l├á mß╗Öt lß╗▒a chß╗ìn tuyß╗çt vß╗¥i. ─É├óy l├á mß╗Öt trong nhß╗»ng tiß╗âu thuyß║┐t trß║╗ th╞í nß╗òi tiß║┐ng nhß║Ñt cß╗ºa Viß╗çt Nam, kß╗â vß╗ü cuß╗Öc phi├¬u l╞░u cß╗ºa mß╗Öt ch├║ dß║┐ m├¿n v├á bß║ín b├¿ cß╗ºa m├¼nh. S├ích c├│ gi├í 55,000─æ v├á c├▓n 90 quyß╗ân.\n\nNß║┐u bß║ín ─æang t├¼m kiß║┐m mß╗Öt cuß╗æn s├ích kh├íc, t├┤i c├│ thß╗â gß╗úi ├╜:\n\n* Sß╗æ ─Éß╗Å cß╗ºa V┼⌐ Trß╗ìng Phß╗Ñng: Mß╗Öt tiß╗âu thuyß║┐t kinh ─æiß╗ân vß╗ü cuß╗Öc sß╗æng cß╗ºa ng╞░ß╗¥i n├┤ng d├ón Viß╗çt Nam, c├│ gi├í 65,000─æ v├á c├▓n 70 quyß╗ân.\n* L├úo Hß║íc cß╗ºa Nam Cao: Mß╗Öt tiß╗âu thuyß║┐t vß╗ü t├¼nh y├¬u v├á cuß╗Öc sß╗æng cß╗ºa ng╞░ß╗¥i n├┤ng d├ón Viß╗çt Nam, c├│ gi├í 42,000─æ v├á c├▓n 85 quyß╗ân.\n\nH├úy cho t├┤i biß║┐t nß║┐u bß║ín cß║ºn th├¬m gß╗úi ├╜!','2026-03-30 05:33:26'),(4,12,'Gß╗úi ├╜ s├ích hay cho t├┤i','T├┤i c├│ thß╗â gß╗úi ├╜ mß╗Öt sß╗æ s├ích hay cho bß║ín. Nß║┐u bß║ín th├¡ch s├ích cß╗ò ─æiß╗ân, t├┤i khuy├¬n bß║ín n├¬n ─æß╗ìc \"Truyß╗çn Kiß╗üu\" cß╗ºa Nguyß╗àn Du hoß║╖c \"Tß╗Öi ├üc V├á H├¼nh Phß║ít\" cß╗ºa Fyodor Dostoevsky.\n\nNß║┐u bß║ín th├¡ch s├ích hiß╗çn ─æß║íi, t├┤i khuy├¬n bß║ín n├¬n ─æß╗ìc \"Nh├á Giß║ú Kim\" cß╗ºa Paulo Coelho hoß║╖c \"B├¬n Nhau Trß╗ìn ─Éß╗¥i\" cß╗ºa Cß╗æ Mß║ín.\n\nNß║┐u bß║ín th├¡ch s├ích t├óm l├╜, t├┤i khuy├¬n bß║ín n├¬n ─æß╗ìc \"─Éß║»c Nh├ón T├óm\" cß╗ºa Dale Carnegie hoß║╖c \"Y├¬u Em Tß╗½ C├íi Nh├¼n ─Éß║ºu Ti├¬n\" cß╗ºa Cß╗æ Mß║ín.\n\nNß║┐u bß║ín th├¡ch s├ích kinh dß╗ï, t├┤i khuy├¬n bß║ín n├¬n ─æß╗ìc \"It - G├ú Hß╗ü Ma Qu├íi\" cß╗ºa Stephen King hoß║╖c \"The Shining - Kh├ích Sß║ín Ma\" cß╗ºa Stephen King.\n\nNß║┐u bß║ín ch╞░a biß║┐t n├¬n ─æß╗ìc s├ích g├¼, t├┤i c├│ thß╗â gi├║p bß║ín lß╗▒a chß╗ìn dß╗▒a tr├¬n sß╗ƒ th├¡ch v├á nhu cß║ºu cß╗ºa bß║ín!','2026-03-30 05:36:16'),(5,10,'Gß╗úi ├╜ s├ích hay cho t├┤i','T├┤i c├│ thß╗â gß╗úi ├╜ cho bß║ín mß╗Öt sß╗æ s├ích hay ─æang c├│ sß║╡n tß║íi nh├á s├ích Bookish.\n\nNß║┐u bß║ín th├¡ch tiß╗âu thuyß║┐t:\n\n- \"Nh├á Giß║ú Kim\" cß╗ºa Paulo Coelho (89,000─æ, c├▓n 50 quyß╗ân) l├á mß╗Öt lß╗▒a chß╗ìn tuyß╗çt vß╗¥i. S├ích kß╗â vß╗ü cuß╗Öc h├ánh tr├¼nh cß╗ºa mß╗Öt ng╞░ß╗¥i ─æ├án ├┤ng t├¼m kiß║┐m niß╗üm tin v├á ├╜ ngh─⌐a trong cuß╗Öc sß╗æng.\n- \"1984\" cß╗ºa George Orwell (115,000─æ, c├▓n 45 quyß╗ân) l├á mß╗Öt t├íc phß║⌐m kinh ─æiß╗ân vß╗ü chß╗º ngh─⌐a thß╗▒c d├ón v├á sß╗▒ kiß╗âm so├ít cß╗ºa ch├¡nh phß╗º.\n\nNß║┐u bß║ín th├¡ch truyß╗çn cß╗ò ─æiß╗ân:\n\n- \"Truyß╗çn Kiß╗üu\" cß╗ºa Nguyß╗àn Du (75,000─æ, c├▓n 0 quyß╗ân) l├á mß╗Öt t├íc phß║⌐m kinh ─æiß╗ân cß╗ºa v─ân hß╗ìc Viß╗çt Nam.\n- \"L├úo Hß║íc\" cß╗ºa Nam Cao (42,000─æ, c├▓n 85 quyß╗ân) l├á mß╗Öt t├íc phß║⌐m ti├¬u biß╗âu vß╗ü v─ân hß╗ìc Viß╗çt Nam.\n\nNß║┐u bß║ín th├¡ch truyß╗çn t├¼nh cß║úm:\n\n- \"B├¬n Nhau Trß╗ìn ─Éß╗¥i\" cß╗ºa Cß╗æ Mß║ín (89,000─æ, c├▓n 99 quyß╗ân) l├á mß╗Öt lß╗▒a chß╗ìn tuyß╗çt vß╗¥i cho nhß╗»ng ai y├¬u th├¡ch truyß╗çn t├¼nh cß║úm.\n- \"Y├¬u Em Tß╗½ C├íi Nh├¼n ─Éß║ºu Ti├¬n\" cß╗ºa Cß╗æ Mß║ín (85,000─æ, c├▓n 90 quyß╗ân) c┼⌐ng l├á mß╗Öt lß╗▒a chß╗ìn hay.\n\nNß║┐u bß║ín th├¡ch truyß╗çn kinh dß╗ï:\n\n- \"It - G├ú Hß╗ü Ma Qu├íi\" cß╗ºa Stephen King (175,000─æ, c├▓n 25 quyß╗ân) l├á mß╗Öt t├íc phß║⌐m kinh ─æiß╗ân vß╗ü kinh dß╗ï.\n- \"The Shining - Kh├ích Sß║ín Ma\" cß╗ºa Stephen King (155,000─æ, c├▓n 30 quyß╗ân) c┼⌐ng l├á mß╗Öt lß╗▒a chß╗ìn hay.\n\nHy vß╗ìng nhß╗»ng gß╗úi ├╜ n├áy sß║╜ gi├║p bß║ín t├¼m ─æ╞░ß╗úc mß╗Öt cuß╗æn s├ích ph├╣ hß╗úp vß╗¢i sß╗ƒ th├¡ch cß╗ºa m├¼nh!','2026-03-30 20:45:02'),(6,12,'c├│ s├ích ng├┤n t├¼nh kh├┤ng','Trong danh s├ích s├ích cß╗ºa ch├║ng t├┤i, kh├┤ng c├│ s├ích ng├┤n t├¼nh. Nß║┐u bß║ín muß╗æn t├¼m s├ích ng├┤n t├¼nh, c├│ thß╗â t├┤i gß╗úi ├╜ mß╗Öt sß╗æ t├íc giß║ú nh╞░ Mß║ín, Diß╗çp Lß║íc V├┤ T├óm, L├óu V┼⌐ T├¼nh. Tuy nhi├¬n, ch├║ng t├┤i kh├┤ng c├│ s├ích ng├┤n t├¼nh trong danh s├ích hiß╗çn tß║íi.\n\nNß║┐u bß║ín muß╗æn mua s├ích ng├┤n t├¼nh, t├┤i c├│ thß╗â ─æß╗ü xuß║Ñt mß╗Öt sß╗æ t├íc giß║ú kh├íc kh├┤ng c├│ trong danh s├ích cß╗ºa ch├║ng t├┤i. H├úy cho t├┤i biß║┐t t├íc giß║ú hoß║╖c thß╗â loß║íi bß║ín mong muß╗æn, t├┤i sß║╜ hß╗ù trß╗ú bß║ín t├¼m kiß║┐m!','2026-03-31 14:58:20'),(7,12,'c├│ s├ích thuß╗Öc thß╗â loß║íi ng├┤n t├¼nh kh├┤ng','T├┤i c├│ thß╗â giß╗¢i thiß╗çu mß╗Öt